// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a dummy token contract that always reverts on transferFrom
        address dummyToken = address(new AlwaysRevertToken());

        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint[] memory amounts = new uint[](1);
        amounts[0] = 100;

        bool ok;
        try c.transfer(from, dummyToken, tos, amounts) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference reverts (ok=false), bug does not (ok=true)
        assertTrue(ok == false, "Reference should revert");
    }
}

contract AlwaysRevertToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}
